"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { X } from "./icons";

// Tag Input: generated by UIX from the design system. Same variants and sizes as the Figma component.

const tagInputVariants = cva(
  "flex w-full flex-wrap items-center transition-colors min-h-10 px-2 py-1 gap-1-5 border border-line-default bg-surface hover:border-line-strong focus-within:ring-3 focus-within:ring-line-focus focus-within:border-line-focus has-[:disabled]:cursor-not-allowed has-[:disabled]:bg-disabled [&_svg]:size-[14px] [&_svg]:shrink-0 rounded-md",
);

export interface TagInputProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size" | "value" | "defaultValue" | "onChange" | "prefix">,
    VariantProps<typeof tagInputVariants> {
  label?: React.ReactNode;
  /** Right-aligned note next to the label, for example "Optional". */
  secondaryLabel?: React.ReactNode;
  /** Message under the field. */
  feedback?: React.ReactNode;
  /** Same as feedback. */
  helper?: React.ReactNode;
  /** Error message; also marks the field invalid and replaces the feedback. */
  error?: string;
  /** The tags (controlled). */
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (tags: string[]) => void;
  /** Stops accepting tags at this count. */
  maxTags?: number;
}

const TagInput = React.forwardRef<HTMLInputElement, TagInputProps>(
  ({ className, label, secondaryLabel, feedback, helper, error, required, id, disabled, value, defaultValue, onValueChange, maxTags, placeholder, ...props }, ref) => {
    const autoId = React.useId();
    const fieldId = id ?? autoId;
    const hintId = fieldId + "-hint";
    const message = error || feedback || helper;
    const hint = message ? { "aria-describedby": hintId } : {};
    const [inner, setInner] = React.useState<string[]>(defaultValue ?? []);
    const items = value ?? inner;
    const [draft, setDraft] = React.useState("");
    const update = (next: string[]) => {
      setInner(next);
      onValueChange?.(next);
    };
    const add = (text: string) => {
      const item = text.trim();
      if (item && !items.includes(item) && (maxTags == null || items.length < maxTags)) update([...items, item]);
      setDraft("");
    };
    return (
      <div data-slot="tag-input" data-kind="field" className={cn("skin-quiet flex w-full flex-col gap-1-5", className)}>
        {label ? (
          <div className="flex items-baseline justify-between gap-2">
            <label htmlFor={fieldId} className={cn("text-label-medium text-fg-primary", disabled && "text-fg-disabled")}>
              {label}
              {required ? <span aria-hidden className="ml-0.5 text-fg-danger">*</span> : null}
            </label>
            {secondaryLabel ? <span className="text-body-small text-fg-tertiary">{secondaryLabel}</span> : null}
          </div>
        ) : null}
        <div data-kind="field" onClick={(event) => event.currentTarget.querySelector("input")?.focus()} className={cn(tagInputVariants({  }), error && "border-line-danger hover:border-line-danger focus-within:border-line-danger focus-within:ring-line-danger")}>
          {items.map((item) => (
            <span key={item} className="inline-flex items-center rounded-full gap-1 px-2 py-1 bg-subtle text-label-medium text-fg-primary">
              {item}
              <button type="button" disabled={disabled} aria-label={"Remove " + item} onClick={() => update(items.filter((other) => other !== item))} className="inline-flex shrink-0 cursor-pointer rounded-full text-icon-secondary hover:text-fg-primary focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus disabled:pointer-events-none">
                <X aria-hidden />
              </button>
            </span>
          ))}
          <input ref={ref} id={fieldId} disabled={disabled || (maxTags != null && items.length >= maxTags)} aria-invalid={!!error} {...hint} placeholder={items.length ? "" : placeholder} {...props} value={draft} onChange={(event) => setDraft(event.target.value)} onBlur={() => add(draft)} onKeyDown={(event) => {
            if (event.key === "Enter" || event.key === ",") {
              event.preventDefault();
              add(draft);
            } else if (event.key === "Backspace" && !draft && items.length) update(items.slice(0, -1));
          }} className="min-w-24 flex-1 bg-transparent outline-none text-body-medium text-fg-primary placeholder:text-fg-tertiary disabled:text-fg-disabled disabled:cursor-not-allowed" />
        </div>
        {message ? (
          <p id={hintId} className={cn("text-body-small text-fg-secondary", error && "text-fg-danger")}>
            {message}
          </p>
        ) : null}
      </div>
    );
  },
);
TagInput.displayName = "TagInput";

export { TagInput, tagInputVariants };
